const nlp_texts = $('Find documents7').first().json.podcast.nlpTexts.map((x) => {
      return {
        ...x,
        speaker:
          x.speaker === "B" || x.speaker.toLowerCase() === 'female'
            ? "zh_female_mizaitongxue_v2_saturn_bigtts"
            : "zh_male_dayixiansheng_v2_saturn_bigtts",
      };
    })

return $input.all().map(() => {
  return {
    data:{
      "action": 3,
      "nlp_texts": nlp_texts,
      "callbackUrl": `${$vars.n8n_origin}/webhook/podcast_result_callback`
    }
  };
});

const backgroundUrls = [
  'https://minioapi.darkred.vip:8888/public/background-music-2-424599.mp3',
  'https://minioapi.darkred.vip:8888/public/Zambolino%20-%20Beautiful%20Day%20(freetouse.com).mp3',
  'https://minioapi.darkred.vip:8888/public/podcast-background-music-385099.mp3',
  'https://minioapi.darkred.vip:8888/public/background-music-453291.mp3'
]

function getRandomBackground() {
  const randomIndex = Math.floor(Math.random() * backgroundUrls.length);
  return backgroundUrls[randomIndex];
}

return {
  data: getRandomBackground()
}

// Get the original section from the Loop node
const originalSection = $('Loop Over Items').first().json

// Add src to media object
const updatedSection = {
  ...originalSection,
  media: {
    ...originalSection.media,
    objectId: $input.first().json.data
  }
};

return [{ json: updatedSection }];

